#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "common.h"
#include "chunk.h"
#include "debug.h"
#include "compiler.h"

// Chapter 17 Challenge 3 (Check syntax without running generated bytecode).
static bool parseSource(const char* source) {
  Chunk chunk;
  initChunk(&chunk);
  bool success = compile(source, &chunk);
  // The temporary chunk is not executed because ?: has no jump bytecode.
  freeChunk(&chunk);
  if (success) printf("Parse OK (syntax only).\n");
  return success;
}

static void repl() {
  char line[1024];
  for (;;) {
    printf("> ");

    if (!fgets(line, sizeof(line), stdin)) {
      printf("\n");
      break;
    }

    parseSource(line);
  }
}
static char* readFile(const char* path) {
  FILE* file = fopen(path, "rb");
  if (file == NULL) {
    fprintf(stderr, "Could not open file \"%s\".\n", path);
    exit(74);
  }

  fseek(file, 0L, SEEK_END);
  size_t fileSize = ftell(file);
  rewind(file);

  char* buffer = (char*)malloc(fileSize + 1);
  if (buffer == NULL) {
    fprintf(stderr, "Not enough memory to read \"%s\".\n", path);
    exit(74);
  }

  size_t bytesRead = fread(buffer, sizeof(char), fileSize, file);
  if (bytesRead < fileSize) {
    fprintf(stderr, "Could not read file \"%s\".\n", path);
    exit(74);
  }

  buffer[bytesRead] = '\0';

  fclose(file);
  return buffer;
}
static void runFile(const char* path) {
  char* source = readFile(path);
  bool success = parseSource(source);
  free(source); // [owner]

  if (!success) exit(65);
}

int main(int argc, const char* argv[]) {
  if (argc == 1) {
    repl();
  } else if (argc == 2) {
    runFile(argv[1]);
  } else {
    fprintf(stderr, "Usage: clox_parse [path]\n");
    exit(64);
  }

  return 0;
}
